export default class App extends HTMLElement{constructor(){super(),slice.attachTemplate(this)}async init(){const t=await slice.build("Navbar",{position:"fixed",logo:{src:"/images/Slice.js-logo.png",path:"/"},items:[{text:"Home",path:"/"},{text:"Components",path:"/docs"}],buttons:[{value:"Change Theme",t:async()=>{const t=slice.stylesManager.themeManager.currentTheme;"Purple"===t?await slice.setTheme("PurpleDark"):await slice.setTheme("Purple")}}]}),e=this.querySelector(".app-navbar");e.appendChild(t);const s=await slice.build("MultiRoute",{routes:[{path:"/",component:"VisualLibraryHome",title:"Slice.js - Home"},{path:"/docs",component:"ComponentsPage",title:"Components Library"}]}),a=this.querySelector(".app-content");a.appendChild(s)}}customElements.define("slice-app",App);